import{_ as t,c as a,o as i,a9 as r,au as o}from"./chunks/framework.Bqk8xQPS.js";const b=JSON.parse('{"title":"MQTT Event Bridge","description":"Use MQTT v5 brokers with PURISTA","frontmatter":{"title":"MQTT Event Bridge","description":"Use MQTT v5 brokers with PURISTA","order":301030},"headers":[],"relativePath":"handbook/3_eco_system/eventbridges/mqtt.md","filePath":"handbook/3_eco_system/eventbridges/mqtt.md","lastUpdated":1775136248000}'),s={name:"handbook/3_eco_system/eventbridges/mqtt.md"};function n(l,e,d,c,p,m){return i(),a("div",null,[...e[0]||(e[0]=[r('<p><img src="'+o+'" alt="MQTT event bridge"></p><h1 id="mqtt-event-bridge" tabindex="-1">MQTT Event Bridge <a class="header-anchor" href="#mqtt-event-bridge" aria-label="Permalink to “MQTT Event Bridge”">​</a></h1><p>The <code>@purista/mqttbridge</code> package integrates MQTT v5 brokers with PURISTA routing semantics.</p><h2 id="delivery-semantics" tabindex="-1">Delivery semantics <a class="header-anchor" href="#delivery-semantics" aria-label="Permalink to “Delivery semantics”">​</a></h2><p>Delivery behavior depends on your MQTT QoS and retention/session settings:</p><ul><li>QoS 0: at-most-once</li><li>QoS 1: at-least-once</li><li>QoS 2: exactly-once on broker/client protocol level (application side effects still must be idempotent)</li></ul><p>Durability and replay are broker- and topic-config dependent.</p><p>For command invocation, PURISTA applies both:</p><ul><li>caller-side pending invocation timeout tracking</li><li>MQTT <code>messageExpiryInterval</code> derived from command timeout for non-event command messages</li></ul><p>This keeps timeout handling predictable while still preferring broker-native expiry where available. Command handlers are single-shot request/response: failures are returned as <code>CommandErrorResponse</code> (<code>UnhandledError</code>) and are not retried by subscription-style delivery loops.</p><h2 id="stream-support" tabindex="-1">Stream support <a class="header-anchor" href="#stream-support" aria-label="Permalink to “Stream support”">​</a></h2><p>PURISTA stream runtime (<code>openStream</code>) is currently not implemented for MQTT bridge.</p><h2 id="topic-strategy" tabindex="-1">Topic strategy <a class="header-anchor" href="#topic-strategy" aria-label="Permalink to “Topic strategy”">​</a></h2><p>PURISTA composes topics from message metadata (type, sender, receiver, tenant/principal, event). Keep prefixes/QoS consistent across all instances.</p><h2 id="reliability-recommendations" tabindex="-1">Reliability recommendations <a class="header-anchor" href="#reliability-recommendations" aria-label="Permalink to “Reliability recommendations”">​</a></h2><ul><li>choose QoS per traffic class (<code>command</code> vs event/subscription)</li><li>align expiry and timeout values intentionally</li><li>use shared subscriptions carefully for scale-out consumers</li><li>test reconnect and retained-session behavior in integration tests</li></ul>',16)])])}const u=t(s,[["render",n]]);export{b as __pageData,u as default};
